// ─── Task Blueprints ──────────────────────────────────────────────────────────

// Compact milestone/task builders — a task is [id, title, description].
type TaskTriple = [string, string, string];
function ms(
  order: number,
  phase: string,
  id: string,
  title: string,
  description: string,
  tasks: TaskTriple[],
): MilestoneDefinition {
  return { id, title, description, phase, order, tasks: tasks.map(([tid, tt, td]) => ({ id: tid, title: tt, description: td })) };
}

